var x = [{
        u: "http://m.xxxbiquge.info/xclass/0/1.html",
        ti: "༺ˇ»`类型分类´«ˇ༻",
        reb: /(\d+)\.html/,
        rea: "{{page}}.html"
    },
    {
        u: "http://m.xxxbiquge.info/quanben.html",
        ti: "༺ˇ»`全本分类´«ˇ༻",
        reb: /(.*)\.html/,
        rea: "$1_{{page}}.html"
    },
    {
        u: "http://m.xxxbiquge.info/ph/week.html",
        ti: "༺ˇ»`周榜´«ˇ༻",
        reb: /(.*)\.html/,
        rea: "$1_{{page}}.html"
    },
    {
        u: "http://m.xxxbiquge.info/ph/month0.html",
        ti: "༺ˇ»`月榜´«ˇ༻",
        reb: /(.*)\.html/,
        rea: "$1_{{page}}.html"
    },
    {
        u: "http://m.xxxbiquge.info/ph/all0.html",
        ti: "༺ˇ»`总榜´«ˇ༻",
        reb: /(.*)\.html/,
        rea: "$1_{{page}}.html"
    }];

x.forEach (i => {
    var o = org.jsoup.Jsoup.parse(java.ajax(i.u));
    var s = o.select('nav.sortChannel_nav>a');
    push(i.ti, "", 1, 1);
    s.forEach(j => {
        var url = String (j.attr("href")).replace(i.reb,i.rea);
        push(j.text(), url, 1, 0.25)
    })
});

JSON.stringify(sort);

